// Der Zaubertrick (optional zu Station 4.3). Spielregeln auf der Website.
World world = new World(500, 500);
world.setBackgroundColor("#ffffff");
Tabelle tabelle = new Tabelle();

/**
 * Ein 5 x 5-Raster aus Feldern: rot steht für 1, blau für 0. Ein Klick dreht ein Feld um.
 * „Los“ fügt rechts eine Spalte und unten eine Zeile mit Prüfbits an.
 * „Prüfen“ lässt den Computer den Fehler suchen (erst nach TODO 1 und 2).
 */
public class Tabelle {
   Rechteck[][] felder;          // felder[zeile][spalte]; Zeile 5 und Spalte 5 sind die Prüfbits
   Knopf losKnopf;
   Knopf pruefKnopf;
   boolean pruefbitsDa = false;

   Tabelle() {
      felder = new Rechteck[6][6];
      for (int zeile = 0; zeile < 5; zeile++) {
         for (int spalte = 0; spalte < 5; spalte++) {
            felder[zeile][spalte] = neuesFeld(zeile, spalte);
         }
      }
      losKnopf = new Knopf(50, 435, 28, "Los", this);
   }

   /** Erzeugt das Feld an dieser Stelle. Prüfbits stehen etwas abgesetzt. */
   Rechteck neuesFeld(int zeile, int spalte) {
      double x = 50 + spalte * 60;
      double y = 50 + zeile * 60;
      if (spalte == 5) {
         x = x + 10;
      }
      if (zeile == 5) {
         y = y + 10;
      }
      return new Rechteck(x, y, 50);
   }

   /** Wird von einem Knopf aufgerufen. */
   void knopfGedrueckt(Knopf knopf) {
      if (knopf == losKnopf && !pruefbitsDa) {
         pruefbitsAnfuegen();
      } else if (knopf == pruefKnopf) {
         fehlerSuchen();
      }
   }

   /** Rechte Spalte und untere Zeile mit Prüfbits anfügen (zuerst alle blau = 0). */
   void pruefbitsAnfuegen() {
      for (int zeile = 0; zeile < 6; zeile++) {
         felder[zeile][5] = neuesFeld(zeile, 5);
      }
      for (int spalte = 0; spalte < 5; spalte++) {      // das Eckfeld [5][5] gibt es schon
         felder[5][spalte] = neuesFeld(5, spalte);
      }
      pruefbitsDa = true;
      losKnopf.setVisible(false);
      pruefKnopf = new Knopf(50, 435, 28, "Prüfen", this);
      println("Färbe die Prüfbits so, dass jede Zeile und jede Spalte eine GERADE Anzahl roter Felder hat.");
   }

   // ---------- Profi: Der Computer als Zauberer ----------

   /**
    * TODO 1: Wie viele rote Felder hat diese Zeile (alle 6 Felder, mit Prüfbit)?
    * Ein Feld f ist rot, wenn f.rot den Wert true hat.
    */
   int roteInZeile(int zeile) {
      int anzahl = 0;
      for (int spalte = 0; spalte < 6; spalte++) {
         if (felder[zeile][spalte].rot) {
            anzahl++;
         }
      }
      return anzahl;
   }

   /**
    * TODO 2: Wie viele rote Felder hat diese Spalte (alle 6 Felder, mit Prüfbit)?
    */
   int roteInSpalte(int spalte) {
      int anzahl = 0;
      for (int zeile = 0; zeile < 6; zeile++) {
         if (felder[zeile][spalte].rot) {
            anzahl++;
         }
      }
      return anzahl;
   }

   /**
    * Sucht die Zeile und die Spalte mit ungerader Anzahl roter Felder.
    * Dort, wo sie sich kreuzen, liegt das veränderte Feld.
    */
   void fehlerSuchen() {
      int fehlerZeile = -1;
      int fehlerSpalte = -1;
      for (int i = 0; i < 6; i++) {
         if (roteInZeile(i) % 2 == 1) {
            fehlerZeile = i;
         }
         if (roteInSpalte(i) % 2 == 1) {
            fehlerSpalte = i;
         }
      }
      if (fehlerZeile == -1 && fehlerSpalte == -1) {
         println("Alle Zeilen und Spalten sind gerade: kein Fehler gefunden.");
      } else if (fehlerZeile != -1 && fehlerSpalte != -1) {
         felder[fehlerZeile][fehlerSpalte].markieren();
         println("Verändert wurde das Feld in Zeile " + (fehlerZeile + 1) + ", Spalte " + (fehlerSpalte + 1) + ".");
      } else {
         println("Seltsam: Nur eine Zeile oder nur eine Spalte ist ungerade. Wurde mehr als ein Feld verändert?");
      }
   }
}

/**
 * Ein Feld des Rasters: rot (1) oder blau (0). Ein Klick dreht es um.
 */
public class Rechteck extends Rectangle {
   boolean rot = false;

   Rechteck(double x, double y, double seitenLaenge) {
      super(x, y, seitenLaenge, seitenLaenge);
      setFillColor(Color.blue);
   }

   public void onMouseDown(double x, double y, int key) {
      if (key == 0) {
         umdrehen();
      }
   }

   void umdrehen() {
      rot = !rot;
      if (rot) {
         setFillColor(Color.red);
      } else {
         setFillColor(Color.blue);
      }
   }

   void markieren() {
      setBorderColor(Color.yellow);
      setBorderWidth(6);
   }
}

/**
 * Ein Knopf, der beim Klick der Tabelle Bescheid gibt.
 */
public class Knopf extends Button {
   Tabelle tabelle;

   Knopf(double x, double y, double fontsize, String text, Tabelle tabelle) {
      super(x, y, fontsize, text);
      this.tabelle = tabelle;
   }

   public void onMouseDown(double x, double y, int key) {
      if (key == 0) {
         tabelle.knopfGedrueckt(this);
      }
   }
}
